import React, { useEffect, useRef, useState } from "react";
import {
  ActivityIndicator,
  Alert,
  Image,
  KeyboardAvoidingView,
  Modal,
  Platform,
  Pressable,
  ScrollView,
  Share,
  StyleSheet,
  Switch,
  Text,
  TextInput,
  View,
  useWindowDimensions,
} from "react-native";
import {
  SafeAreaProvider,
  SafeAreaInsetsContext,
  SafeAreaView,
  useSafeAreaInsets,
} from "react-native-safe-area-context";
import { PreviewChrome } from "./src/preview-chrome";
import { StatusBar } from "expo-status-bar";
import { LinearGradient } from "expo-linear-gradient";
import { BlurView } from "expo-blur";
import { VideoView, useVideoPlayer } from "expo-video";
import { CameraView, useCameraPermissions } from "expo-camera";
import * as ImagePicker from "expo-image-picker";
import * as Haptics from "expo-haptics";
import { useAudioPlayer } from "expo-audio";
import {
  colors,
  communities,
  creators,
  gifts,
  interests,
  photos,
  reels,
  tracks,
  type PhotoKey,
} from "./src/data";
import {
  Action,
  Avatar,
  Divider,
  Header,
  Icon,
  IconButton,
  Photo,
  SearchField,
  Section,
  Shade,
  Sheet,
  s,
  type IconName,
} from "./src/ui";
import { useDemoStore } from "./src/store";
import { demoVideoUrl, livePlaybackUrl } from "./src/services";
import { createDemoMelody, persistStoryPhoto } from "./src/media";
type Tab = "Discover" | "Browse" | "Communities" | "Messaging" | "Profile";
type Screen =
  | Tab
  | "Saved"
  | "Followers"
  | "Community"
  | "Chat"
  | "Camera"
  | "Story"
  | "Share";
type SheetName =
  | "menu"
  | "gift"
  | "music"
  | "edit"
  | "notifications"
  | "settings"
  | "help"
  | "select"
  | null;
const tabs: { title: Tab; icon: IconName }[] = [
  { title: "Discover", icon: "compass" },
  { title: "Browse", icon: "search" },
  { title: "Communities", icon: "people" },
  { title: "Messaging", icon: "chatbubbles" },
  { title: "Profile", icon: "person-circle" },
];
export default function App() {
  const app = (
    <>
      <StatusBar style="light" />
      <RNL />
      <PreviewChrome />
    </>
  );
  return (
    <SafeAreaProvider>
      {Platform.OS === "web" ? (
        <SafeAreaInsetsContext.Provider
          value={{ top: 59, bottom: 34, left: 0, right: 0 }}
        >
          {app}
        </SafeAreaInsetsContext.Provider>
      ) : (
        app
      )}
    </SafeAreaProvider>
  );
}
function RNL() {
  const { state, setState, update, toggle, ready, storageError } =
    useDemoStore();
  const [screen, setScreen] = useState<Screen>("Discover");
  const [tab, setTab] = useState<Tab>("Discover");
  const [sheet, setSheet] = useState<SheetName>(null);
  const [step, setStep] = useState(0);
  const [search, setSearch] = useState("");
  const [queryTab, setQueryTab] = useState("Reels");
  const [activeReel, setActiveReel] = useState<(typeof reels)[number] | null>(
    null,
  );
  const [community, setCommunity] = useState(communities[0]);
  const [chat, setChat] = useState(creators[2]);
  const [draft, setDraft] = useState("");
  const [gift, setGift] = useState(1);
  const [giftsSent, setGiftsSent] = useState<string[]>([]);
  const [storyUri, setStoryUri] = useState(photos.hike);
  const [caption, setCaption] = useState("");
  const [audience, setAudience] = useState("Main stories");
  const [filter, setFilter] = useState("Default");
  const [track, setTrack] = useState("");
  const [audioStart, setAudioStart] = useState(0);
  const [musicSearch, setMusicSearch] = useState("");
  const [audioSelection, setAudioSelection] = useState(false);
  const [playingTrack, setPlayingTrack] = useState("");
  const [permission, requestPermission] = useCameraPermissions();
  const [cameraEnabled, setCameraEnabled] = useState(false);
  const [facing, setFacing] = useState<"front" | "back">("back");
  const [flash, setFlash] = useState(false);
  const [captureBusy, setCaptureBusy] = useState(false);
  const [cameraReady, setCameraReady] = useState(false);
  const [selector, setSelector] = useState<{
    title: string;
    options: string[];
    onSelect: (v: string) => void;
  }>({ title: "", options: [], onSelect: () => {} });
  const [editName, setEditName] = useState(state.name);
  const [editBio, setEditBio] = useState(state.bio);
  const [joinedOnly, setJoinedOnly] = useState(false);
  const [toast, setToast] = useState("");
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const camera = useRef<CameraView>(null);
  const chatScroll = useRef<ScrollView>(null);
  const [demoAudio] = useState(createDemoMelody);
  const player = useAudioPlayer(demoAudio);
  const insets = useSafeAreaInsets();
  const { width } = useWindowDimensions();
  const cardWidth = Math.min((width - 32 - 8) / 2, 260);
  const notice = (text: string) => {
    setToast(text);
    if (toastTimer.current) clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(""), 3500);
  };
  useEffect(
    () => () => {
      if (toastTimer.current) clearTimeout(toastTimer.current);
    },
    [],
  );
  useEffect(() => {
    if (storageError)
      notice("Storage is unavailable. Changes will last for this session.");
  }, [storageError]);
  const go = (t: Tab) => {
    setTab(t);
    setScreen(t);
    setSearch("");
    setSheet(null);
    setDraft("");
  };
  const closeSheet = () => {
    player.pause();
    setPlayingTrack("");
    setSheet(null);
  };
  const select = (
    title: string,
    options: string[],
    onSelect: (v: string) => void,
  ) => {
    setSelector({ title, options, onSelect });
    setSheet("select");
  };
  const openCamera = () => {
    setScreen("Camera");
    setCameraEnabled(false);
    setCaption("");
    setTrack("");
    setAudioSelection(false);
  };
  const pickPhoto = async () => {
    try {
      const result = await ImagePicker.launchImageLibraryAsync({
        mediaTypes: ["images"],
        allowsEditing: true,
        aspect: [9, 16],
        quality: 0.85,
      });
      if (!result.canceled) {
        setStoryUri(result.assets[0].uri);
        setScreen("Story");
      }
    } catch {
      Alert.alert(
        "Photo access needed",
        "Enable photo access in iOS Settings to choose an image.",
      );
    }
  };
  const capture = async () => {
    if (captureBusy) return;
    setCaptureBusy(true);
    try {
      if (cameraEnabled && cameraReady) {
        const picture = await camera.current?.takePictureAsync({
          quality: 0.85,
        });
        if (!picture) throw new Error("No photo");
        setStoryUri(picture.uri);
      } else setStoryUri(photos.hike);
      Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success).catch(
        () => {},
      );
      setScreen("Story");
    } catch {
      notice("The camera could not capture a photo. Please try again.");
    } finally {
      setCaptureBusy(false);
    }
  };
  const creatorRow = (c: (typeof creators)[number]) => (
    <View style={st.creatorRow} key={c.id}>
      <Avatar index={c.avatar} ring={c.avatar % 2 === 0} />
      <View style={{ flex: 1 }}>
        <Text style={st.creatorName}>{c.name}</Text>
        <Text style={[s.muted, { marginTop: 5 }]}>@{c.handle}</Text>
      </View>
      <Action outline onPress={() => toggle("following", c.id)}>
        <Icon
          name={state.following.includes(c.id) ? "checkmark" : "person-add"}
          size={16}
        />
        <Text style={s.small}>
          {state.following.includes(c.id) ? "Following" : "Follow"}
        </Text>
      </Action>
    </View>
  );
  const card = (r: (typeof reels)[number], compact = false) => (
    <Pressable
      key={r.id}
      accessibilityRole="button"
      accessibilityLabel={`${r.live ? "Live: " : ""}${r.title} by ${r.user}`}
      onPress={() => setActiveReel(r)}
      style={[
        st.reelCard,
        {
          width: compact ? cardWidth : 128,
          height: compact ? cardWidth * (240 / 176) : 190,
        },
      ]}
    >
      <Photo image={r.image} />
      <Shade />
      {r.live && (
        <View style={st.liveBadge}>
          <Text style={st.liveText}>LIVE</Text>
        </View>
      )}
      <View style={st.reelCopy}>
        <Text style={st.reelUser}>@{r.user}</Text>
        <View style={[s.row, { marginTop: 7 }]}>
          <Icon name="heart" size={13} />
          <Text style={st.reelStats}>{r.likes}</Text>
          <Icon name="chatbox" size={13} />
          <Text style={st.reelStats}>{r.comments}</Text>
        </View>
      </View>
    </Pressable>
  );
  const filteredReels = reels.filter((r) =>
    `${r.title} ${r.tag} ${r.user}`
      .toLowerCase()
      .includes(search.toLowerCase()),
  );
  if (!ready)
    return (
      <View style={[s.root, st.center]}>
        <ActivityIndicator color={colors.accent} />
      </View>
    );
  return (
    <LinearGradient colors={["#222222", "#111111"]} style={s.root}>
      <SafeAreaView
        style={[s.root, { backgroundColor: "transparent" }]}
        edges={["top"]}
      >
        {!state.onboarded ? (
          <>
            <Header
              title="Get started"
              left="chevron-back"
              onLeft={() =>
                step > 0 ? setStep(step - 1) : update({ onboarded: true })
              }
              right="help-circle-outline"
              onRight={() => setSheet("help")}
            />
            <ScrollView
              showsVerticalScrollIndicator={false}
              contentContainerStyle={{
                padding: 20,
                paddingBottom: step === 0 ? 62 : 50,
                flexGrow: 1,
              }}
            >
              <Text
                style={[
                  s.title,
                  {
                    textAlign: "center",
                    marginTop: 12,
                    marginBottom: step === 0 ? 0 : 12,
                  },
                ]}
              >
                {step === 0
                  ? "Tell us about you"
                  : step === 1
                    ? "Choose your interests"
                    : "Follow creators"}
              </Text>
              {step === 0 ? (
                <>
                  <Divider first>BIRTHDAY</Divider>
                  <View style={[s.row, { gap: 12 }]}>
                    {state.birthday.map((v, i) => (
                      <Pressable
                        key={i}
                        style={[st.select, { flex: 1 }]}
                        onPress={() =>
                          select(
                            ["Day", "Month", "Year"][i],
                            i === 0
                              ? Array.from({ length: 31 }, (_, j) => `${j + 1}`)
                              : i === 1
                                ? [
                                    "Jan",
                                    "Feb",
                                    "Mar",
                                    "Apr",
                                    "May",
                                    "Jun",
                                    "Jul",
                                    "Aug",
                                    "Sep",
                                    "Oct",
                                    "Nov",
                                    "Dec",
                                  ]
                                : Array.from(
                                    { length: 90 },
                                    (_, j) => `${2010 - j}`,
                                  ),
                            (value) =>
                              update({
                                birthday: state.birthday.map((b, j) =>
                                  j === i ? value : b,
                                ),
                              }),
                          )
                        }
                      >
                        <Text style={s.text}>{v}</Text>
                        <Icon
                          name="chevron-down"
                          color={colors.muted}
                          size={16}
                        />
                      </Pressable>
                    ))}
                  </View>
                  <Divider>GENDER</Divider>
                  <View style={st.segmented}>
                    {["Male", "Female"].map((g) => (
                      <Pressable
                        key={g}
                        style={{ flex: 1 }}
                        onPress={() => update({ gender: g })}
                      >
                        {state.gender === g ? (
                          <LinearGradient
                            colors={colors.gradient}
                            style={st.segment}
                          >
                            <Text style={s.text}>{g}</Text>
                          </LinearGradient>
                        ) : (
                          <View style={st.segment}>
                            <Text style={s.text}>{g}</Text>
                          </View>
                        )}
                      </Pressable>
                    ))}
                  </View>
                  <Divider>NATIONALITY</Divider>
                  <Pressable
                    style={st.select}
                    onPress={() =>
                      select(
                        "Nationality",
                        [
                          "🇮🇹 Italian",
                          "🇲🇦 Moroccan",
                          "🇺🇸 American",
                          "🇬🇧 British",
                          "🇫🇷 French",
                          "🌍 Other",
                        ],
                        (v) => update({ nationality: v }),
                      )
                    }
                  >
                    <Text style={s.text}>{state.nationality}</Text>
                    <Icon name="chevron-down" color={colors.muted} size={16} />
                  </Pressable>
                  <Divider>LANGUAGE</Divider>
                  <Pressable
                    style={st.select}
                    onPress={() =>
                      select(
                        "Language",
                        [
                          "🇬🇧 English",
                          "🇫🇷 Français",
                          "🇮🇹 Italiano",
                          "🇲🇦 العربية",
                        ],
                        (v) => update({ language: v }),
                      )
                    }
                  >
                    <Text style={s.text}>{state.language}</Text>
                    <Icon name="chevron-down" color={colors.muted} size={16} />
                  </Pressable>
                </>
              ) : step === 1 ? (
                <>
                  <Text style={[s.muted, st.centerText]}>
                    The things you love help us find your kind of inspiration.
                  </Text>
                  <View style={st.chips}>
                    {interests.map((i) => (
                      <Pressable
                        key={i}
                        accessibilityRole="checkbox"
                        accessibilityState={{
                          checked: state.interests.includes(i),
                        }}
                        style={[
                          st.chip,
                          state.interests.includes(i) && st.chipSelected,
                        ]}
                        onPress={() => toggle("interests", i)}
                      >
                        <Text style={s.small}>{i}</Text>
                      </Pressable>
                    ))}
                  </View>
                </>
              ) : (
                <>
                  <Text
                    style={[
                      s.muted,
                      st.centerText,
                      { fontSize: 14, lineHeight: 18, marginBottom: 24 },
                    ]}
                  >
                    Meet creators who inspire you. Follow a few favorites to
                    make your feed feel like you.
                  </Text>
                  {creators.map(creatorRow)}
                </>
              )}
              <View style={{ flex: 1, minHeight: step === 2 ? 4 : 32 }} />
              <Action
                onPress={() =>
                  step < 2 ? setStep(step + 1) : update({ onboarded: true })
                }
              >
                Next
              </Action>
              {step > 0 && (
                <Pressable
                  style={st.skip}
                  onPress={() =>
                    step === 1 ? setStep(2) : update({ onboarded: true })
                  }
                >
                  <Text style={s.text}>Skip →</Text>
                </Pressable>
              )}
            </ScrollView>
          </>
        ) : (
          <>
            {screen !== "Camera" && (
              <Header
                title={
                  screen === "Community"
                    ? community.name
                    : screen === "Chat"
                      ? `@${chat.handle}`
                      : ["Story", "Share"].includes(screen)
                        ? "Add story"
                        : screen === "Followers"
                          ? "My followers"
                          : screen
                }
                left={
                  ["Community", "Chat", "Followers", "Saved"].includes(screen)
                    ? "chevron-back"
                    : ["Story", "Share"].includes(screen)
                      ? "close"
                      : screen === "Communities"
                        ? "add"
                        : "camera"
                }
                onLeft={() =>
                  ["Community", "Chat", "Followers", "Saved"].includes(screen)
                    ? setScreen(tab)
                    : ["Story", "Share"].includes(screen)
                      ? setScreen(tab)
                      : openCamera()
                }
                right={
                  screen === "Profile"
                    ? "menu"
                    : ["Community", "Chat", "Story", "Share"].includes(screen)
                      ? "ellipsis-vertical"
                      : "notifications"
                }
                onRight={() =>
                  setSheet(
                    screen === "Profile"
                      ? "menu"
                      : ["Community", "Chat", "Story", "Share"].includes(screen)
                        ? "help"
                        : "notifications",
                  )
                }
              />
            )}
            {screen === "Discover" && (
              <ScrollView
                showsVerticalScrollIndicator={false}
                contentContainerStyle={{
                  paddingVertical: 24,
                  paddingBottom: 110,
                }}
              >
                <View style={st.sectionPad}>
                  <Section title="What’s new" onMore={() => go("Browse")} />
                </View>
                <ScrollView
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  contentContainerStyle={st.horizontal}
                >
                  {reels.slice(0, 3).map((r) => card(r))}
                </ScrollView>
                <View style={[st.sectionPad, { marginTop: 24 }]}>
                  <Section
                    title="Creators to follow"
                    onMore={() => setScreen("Followers")}
                  />
                </View>
                <ScrollView
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  contentContainerStyle={st.horizontal}
                >
                  {creators.map((c) => (
                    <Pressable
                      key={c.id}
                      onPress={() => toggle("following", c.id)}
                      accessibilityLabel={`${state.following.includes(c.id) ? "Unfollow" : "Follow"} ${c.name}`}
                      style={st.creatorTile}
                    >
                      <Avatar
                        index={c.avatar}
                        size={64}
                        ring={state.following.includes(c.id)}
                      />
                    </Pressable>
                  ))}
                </ScrollView>
                <View style={[st.sectionPad, { marginTop: 24 }]}>
                  <Section
                    title="Communities"
                    onMore={() => go("Communities")}
                  />
                </View>
                <ScrollView
                  horizontal
                  showsHorizontalScrollIndicator={false}
                  contentContainerStyle={st.horizontal}
                >
                  {communities.map((c) => (
                    <Pressable
                      style={st.communityTile}
                      key={c.id}
                      onPress={() => {
                        setCommunity(c);
                        setTab("Communities");
                        setScreen("Community");
                      }}
                    >
                      <Photo image={c.image} />
                      <Shade />
                      <View style={st.reelCopy}>
                        <Text style={st.reelUser}>{c.short}</Text>
                        <View style={[s.row, { marginTop: 5 }]}>
                          <Icon name="people" size={13} />
                          <Text style={s.small}>{c.members}</Text>
                        </View>
                      </View>
                    </Pressable>
                  ))}
                </ScrollView>
              </ScrollView>
            )}
            {(screen === "Browse" || screen === "Saved") && (
              <ScrollView
                contentContainerStyle={[
                  s.content,
                  { paddingHorizontal: 16, paddingBottom: 110 },
                ]}
              >
                <SearchField
                  placeholder="Search for a reel…"
                  value={search}
                  onChangeText={setSearch}
                />
                {!!search && (
                  <View style={st.queryTabs}>
                    {["Reels", "Hashtags", "Accounts"].map((t) => (
                      <Pressable
                        key={t}
                        style={[st.queryTab, queryTab === t && st.queryActive]}
                        onPress={() => setQueryTab(t)}
                      >
                        <Text style={s.text}>{t}</Text>
                      </Pressable>
                    ))}
                  </View>
                )}
                {search && queryTab === "Accounts" ? (
                  creators
                    .filter((c) => c.handle.includes(search.toLowerCase()))
                    .map(creatorRow)
                ) : search && queryTab === "Hashtags" ? (
                  ["Art", "Nature", "Travel", "Music", "Lifestyle"]
                    .filter((t) =>
                      t.toLowerCase().includes(search.toLowerCase()),
                    )
                    .map((t) => (
                      <Pressable
                        key={t}
                        style={st.creatorRow}
                        onPress={() => {
                          setSearch(t);
                          setQueryTab("Reels");
                        }}
                      >
                        <Text style={s.title}>#</Text>
                        <Text style={s.text}>{t}</Text>
                      </Pressable>
                    ))
                ) : (
                  <View style={st.grid}>
                    {filteredReels
                      .filter(
                        (r) => screen !== "Saved" || state.saved.includes(r.id),
                      )
                      .map((r) => card(r, true))}
                  </View>
                )}
                {(!filteredReels.length ||
                  (screen === "Saved" && !state.saved.length)) && (
                  <Text style={[s.muted, st.centerText]}>
                    No moments found. Try a new search or save a reel.
                  </Text>
                )}
              </ScrollView>
            )}
            {screen === "Followers" && (
              <ScrollView
                contentContainerStyle={[s.content, { paddingBottom: 110 }]}
              >
                {creators.map(creatorRow)}
              </ScrollView>
            )}
            {screen === "Communities" && (
              <ScrollView
                contentContainerStyle={[s.content, { paddingBottom: 110 }]}
              >
                <SearchField
                  placeholder="Search for a community…"
                  value={search}
                  onChangeText={setSearch}
                />
                <View style={[s.row, { marginBottom: 24 }]}>
                  {["Explore", "Joined"].map((t, i) => (
                    <Pressable
                      key={t}
                      onPress={() => setJoinedOnly(!!i)}
                      style={[st.chip, joinedOnly === !!i && st.chipSelected]}
                    >
                      <Text style={s.small}>{t}</Text>
                    </Pressable>
                  ))}
                </View>
                {communities
                  .filter(
                    (c) =>
                      (!joinedOnly || state.joined.includes(c.id)) &&
                      c.name.toLowerCase().includes(search.toLowerCase()),
                  )
                  .map((c) => (
                    <View key={c.id} style={st.communityCard}>
                      <Pressable
                        onPress={() => {
                          setCommunity(c);
                          setScreen("Community");
                        }}
                        style={StyleSheet.absoluteFill}
                      >
                        <Photo image={c.image} />
                        <Shade />
                      </Pressable>
                      <View style={[s.row, { alignItems: "flex-end" }]}>
                        <View style={{ flex: 1 }}>
                          <Text
                            style={[
                              s.text,
                              { fontWeight: "600", fontSize: 20 },
                            ]}
                          >
                            {c.name}
                          </Text>
                          <Text
                            style={[s.muted, { marginTop: 8, color: "#ddd" }]}
                          >
                            ♟ {c.members} MEMBERS
                          </Text>
                        </View>
                        <Action outline onPress={() => toggle("joined", c.id)}>
                          <Icon
                            name={
                              state.joined.includes(c.id) ? "checkmark" : "add"
                            }
                            size={18}
                          />
                          <Text style={s.small}>
                            {state.joined.includes(c.id) ? "Joined" : "Join"}
                          </Text>
                        </Action>
                      </View>
                    </View>
                  ))}
              </ScrollView>
            )}
            {screen === "Community" && (
              <KeyboardAvoidingView
                style={{ flex: 1 }}
                behavior={Platform.OS === "ios" ? "padding" : undefined}
              >
                <ScrollView contentContainerStyle={{ paddingBottom: 30 }}>
                  {[
                    ...(state.posts[community.id] || []),
                    "A reminder to make something just for the joy of making it. What are you working on today?",
                    "A little glimpse into my creative world. Falling in love with these colors again.",
                  ].map((p, i) => (
                    <View style={st.post} key={i}>
                      <View style={s.row}>
                        <Avatar index={i % 6} size={36} />
                        <View style={{ flex: 1 }}>
                          <Text style={s.text}>
                            @
                            {i < (state.posts[community.id]?.length || 0)
                              ? state.handle
                              : i % 2
                                ? "mariam"
                                : "jackyjones"}
                          </Text>
                          <Text style={s.muted}>2 min ago</Text>
                        </View>
                        <IconButton
                          name="ellipsis-vertical"
                          label="Post details"
                          onPress={() => notice("Community demo post")}
                          size={32}
                        />
                      </View>
                      <Text
                        style={[s.text, { lineHeight: 24, marginVertical: 20 }]}
                      >
                        {p}
                      </Text>
                      {i === 1 && (
                        <Image
                          source={{ uri: photos[community.image] }}
                          style={st.postImage}
                        />
                      )}
                      <View
                        style={[
