                        style={{
                          color: colors.muted,
                          fontSize: 10,
                          marginTop: 6,
                        }}
                      >
                        {t.artist}
                      </Text>
                    </View>
                    <IconButton
                      name={playingTrack === t.title ? "pause" : "play"}
                      size={32}
                      label={`Preview ${t.title}`}
                      onPress={() => {
                        if (playingTrack === t.title) {
                          player.pause();
                          setPlayingTrack("");
                        } else {
                          player.seekTo(0);
                          player.play();
                          setPlayingTrack(t.title);
                        }
                      }}
                    />
                    <IconButton
                      gradient
                      name="add"
                      size={34}
                      label={`Use ${t.title}`}
                      onPress={() => {
                        setTrack(t.title);
                        setAudioSelection(true);
                        closeSheet();
                      }}
                    />
                  </View>
                ))}
            </>
          )}
        </Sheet>
        <Modal
          visible={activeReel !== null}
          animationType="slide"
          onRequestClose={() => setActiveReel(null)}
          statusBarTranslucent
        >
          {activeReel && (
            <ReelViewer
              reel={activeReel}
              following={state.following.includes(activeReel.user)}
              saved={state.saved.includes(activeReel.id)}
              liked={state.liked.includes(activeReel.id)}
              onFollow={() => toggle("following", activeReel.user)}
              onSave={() => toggle("saved", activeReel.id)}
              onLike={() => toggle("liked", activeReel.id)}
              onClose={() => setActiveReel(null)}
              onGift={() => setSheet("gift")}
              giftsSent={giftsSent}
            />
          )}
          <Sheet
            title="Send gift"
            visible={sheet === "gift"}
            onClose={() => setSheet(null)}
          >
            <View
              style={[
                s.row,
                { justifyContent: "space-between", marginBottom: 20 },
              ]}
            >
              <Text style={s.muted}>A little joy goes a long way.</Text>
              <Text style={s.text}>★ {state.points}</Text>
            </View>
            <View style={st.giftGrid}>
              {gifts.map((g, i) => (
                <Pressable
                  key={g.name}
                  style={[st.gift, gift === i && { borderColor: "#aaa" }]}
                  onPress={() => setGift(i)}
                  accessibilityRole="radio"
                  accessibilityState={{ selected: gift === i }}
                >
                  <Text style={{ fontSize: 40 }}>{g.emoji}</Text>
                  <Text style={[s.text, { marginTop: 8, fontSize: 14 }]}>
                    {g.name}
                  </Text>
                  <Text
                    style={{ color: colors.accent, fontSize: 10, marginTop: 7 }}
                  >
                    {g.points} POINTS
                  </Text>
                </Pressable>
              ))}
            </View>
            <Action
              disabled={state.points < gifts[gift].points}
              style={{ marginTop: 24 }}
              onPress={() => {
                const g = gifts[gift];
                if (state.points < g.points) return;
                setState((prev) => ({
                  ...prev,
                  points: prev.points - g.points,
                }));
                setGiftsSent((prev) => [...prev, `${g.emoji} 1× ${g.name}`]);
                setSheet(null);
                Haptics.notificationAsync(
                  Haptics.NotificationFeedbackType.Success,
                ).catch(() => {});
              }}
            >
              {state.points < gifts[gift].points
                ? "Not enough demo points"
                : "Send gift"}
            </Action>
            <Text
              style={[s.muted, st.centerText, { fontSize: 10, marginTop: 12 }]}
            >
              Demo credits · No real money
            </Text>
          </Sheet>
        </Modal>
        {toast && (
          <View
            accessibilityRole="alert"
            style={[st.toast, { bottom: insets.bottom + 70 }]}
          >
            <Icon name="checkmark-circle" color={colors.accent} size={18} />
            <Text style={[s.small, { flex: 1 }]}>{toast}</Text>
          </View>
        )}
      </SafeAreaView>
    </LinearGradient>
  );
}
function ReelViewer({
  reel,
  following,
  saved,
  liked,
  onFollow,
  onSave,
  onLike,
  onClose,
  onGift,
  giftsSent,
}: {
  reel: (typeof reels)[number];
  following: boolean;
  saved: boolean;
  liked: boolean;
  onFollow: () => void;
  onSave: () => void;
  onLike: () => void;
  onClose: () => void;
  onGift: () => void;
  giftsSent: string[];
}) {
  const player = useVideoPlayer(
    reel.live ? livePlaybackUrl : demoVideoUrl,
    (p) => {
      p.loop = true;
      if (!reel.live) p.play();
    },
  );
  const [draft, setDraft] = useState("");
  const [error, setError] = useState(false);
  useEffect(() => {
    const sub = player.addListener("statusChange", ({ status }) =>
      setError(status === "error"),
    );
    return () => sub.remove();
  }, [player]);
  const [comments, setComments] = useState([
    { user: "anhild", text: "Can’t wait to join you" },
    { user: "nara", text: "Too beautiful to describe!! 😍" },
    { user: "brinhildr", text: "Amazing view!" },
  ]);
  return (
    <View style={s.root}>
      <StatusBar style="light" />
      <Image
        source={{ uri: photos[reel.image] }}
        style={StyleSheet.absoluteFillObject}
      />
      {(!reel.live || livePlaybackUrl) && !error && (
        <VideoView
          player={player}
          style={StyleSheet.absoluteFillObject}
          contentFit="cover"
          nativeControls={!reel.live}
        />
      )}
      <Shade />
      <SafeAreaView style={{ flex: 1 }}>
        <View style={[s.row, { padding: 16 }]}>
          <Avatar
            index={creators.find((c) => c.id === reel.user)?.avatar || 0}
            size={44}
          />
          <View style={{ flex: 1 }}>
            <View style={s.row}>
              <Text style={[s.text, { fontWeight: "600" }]}>@{reel.user}</Text>
              {reel.live && (
                <View
                  style={[
                    st.liveBadge,
                    { position: "relative", top: 0, left: 0 },
                  ]}
                >
                  <Text style={st.liveText}>LIVE</Text>
                </View>
              )}
            </View>
            <Text style={{ fontSize: 11, color: "#ccc", marginTop: 5 }}>
              {reel.live && !livePlaybackUrl ? "Demo live room" : reel.title}
            </Text>
          </View>
          <Action outline onPress={onFollow}>
            <Text style={s.small}>{following ? "Following" : "+ Follow"}</Text>
          </Action>
          <IconButton
            name="close"
            label="Close reel"
            onPress={onClose}
            size={34}
          />
        </View>
        {error && (
          <Text style={[s.muted, { padding: 24, backgroundColor: "#000a" }]}>
            Video could not load. Check your connection and reopen this reel.
          </Text>
        )}
        <View style={{ flex: 1 }} />
        <View style={{ position: "absolute", right: 20, top: 145, gap: 16 }}>
          {giftsSent.map((g, i) => (
            <Text key={i} style={s.text}>
              {g}
            </Text>
          ))}
        </View>
        {reel.live && (
          <View style={{ padding: 16, gap: 9, alignItems: "flex-start" }}>
            {comments.slice(-4).map((c, i) => (
              <View key={i} style={st.liveComment}>
                <Text style={[s.text, { fontWeight: "600" }]}>@{c.user}</Text>
                <Text style={[s.text, { marginTop: 6, fontSize: 14 }]}>
                  {c.text}
                </Text>
              </View>
            ))}
          </View>
        )}
        <View style={[s.row, { padding: 16 }]}>
          {reel.live ? (
            <>
              <TextInput
                value={draft}
                onChangeText={setDraft}
                onSubmitEditing={() => {
                  if (draft.trim()) {
                    setComments((p) => [
                      ...p,
                      { user: "you", text: draft.trim() },
                    ]);
                    setDraft("");
                  }
                }}
                placeholder="Type something…"
                placeholderTextColor="#bbb"
                style={[
                  st.textInput,
                  {
                    flex: 1,
                    backgroundColor: "#0008",
                    marginTop: 0,
                    borderRadius: 30,
                  },
                ]}
              />
              <IconButton name="star" label="Send gift" onPress={onGift} />
              <IconButton
                gradient
                name={draft.trim() ? "send" : "heart"}
                size={48}
                label={draft.trim() ? "Send comment" : "Like live stream"}
                onPress={() => {
                  if (draft.trim()) {
                    setComments((p) => [
                      ...p,
                      { user: "you", text: draft.trim() },
                    ]);
                    setDraft("");
                  } else onLike();
                }}
              />
            </>
          ) : (
            <>
              <IconButton
                name={liked ? "heart" : "heart-outline"}
                label="Like reel"
                onPress={onLike}
              />
              <Text style={s.small}>{liked ? "12.3k" : reel.likes}</Text>
              <View style={{ flex: 1 }} />
              <IconButton
                name={saved ? "bookmark" : "bookmark-outline"}
                label={saved ? "Unsave reel" : "Save reel"}
                onPress={onSave}
              />
              <IconButton
                name="share-social"
                label="Share reel"
                onPress={() =>
                  Share.share({
                    message: `${reel.title} by @${reel.user} — RNL`,
                  })
                }
              />
            </>
          )}
        </View>
      </SafeAreaView>
      <PreviewChrome />
    </View>
  );
}
