import React, { type ReactNode } from "react";
import {
  View,
  Text,
  Pressable,
  Image,
  Modal,
  ScrollView,
  StyleSheet,
  TextInput,
  PanResponder,
  type ViewStyle,
  type StyleProp,
  type TextInputProps,
} from "react-native";
import { PreviewChrome } from "./preview-chrome";
import { Ionicons } from "@expo/vector-icons";
import { LinearGradient } from "expo-linear-gradient";
import { BlurView } from "expo-blur";
