import { useSafeAreaInsets } from "react-native-safe-area-context";
import * as Haptics from "expo-haptics";
import { colors, avatarSvg, photos, type PhotoKey, space } from "./data";
export type IconName = React.ComponentProps<typeof Ionicons>["name"];
export function Icon({
  name,
  size = 23,
  color = colors.text,
}: {
  name: IconName;
  size?: number;
  color?: string;
}) {
  return <Ionicons name={name} size={size} color={color} />;
}
export function Avatar({
  index = 0,
  size = 48,
  ring = false,
}: {
  index?: number;
  size?: number;
  ring?: boolean;
}) {
  const content = (
    <View
      style={{
        borderRadius: size,
        overflow: "hidden",
        borderWidth: ring ? 2 : 0,
        borderColor: colors.background,
      }}
    >
      <SvgXml
        xml={avatarSvg(index)}
        width={size - (ring ? 6 : 0)}
        height={size - (ring ? 6 : 0)}
      />
    </View>
  );
  return ring ? (
    <LinearGradient
      colors={colors.gradient}
      style={{ padding: 1, borderRadius: size }}
    >
      {content}
    </LinearGradient>
  ) : (
    content
  );
}
export function Action({
  children,
  onPress,
  outline = false,
  disabled = false,
  style,
  label,
}: {
  children: ReactNode;
  onPress: () => void;
  outline?: boolean;
  disabled?: boolean;
  style?: StyleProp<ViewStyle>;
  label?: string;
}) {
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityState={{ disabled }}
      disabled={disabled}
      onPress={() => {
        Haptics.selectionAsync().catch(() => {});
        onPress();
      }}
      style={({ pressed }) => [
        { opacity: disabled ? 0.4 : pressed ? 0.7 : 1 },
        style,
      ]}
    >
      {outline ? (
        <View style={s.outlineButton}>
          {typeof children === "string" ? (
            <Text style={s.buttonText}>{children}</Text>
          ) : (
            children
          )}
        </View>
      ) : (
        <LinearGradient colors={colors.gradient} style={s.gradientButton}>
          {typeof children === "string" ? (
            <Text style={s.buttonText}>{children}</Text>
          ) : (
            children
          )}
        </LinearGradient>
      )}
    </Pressable>
  );
}
export function IconButton({
  name,
  onPress,
  label,
  gradient = false,
  size = 40,
}: {
  name: IconName;
  onPress: () => void;
  label: string;
  gradient?: boolean;
  size?: number;
}) {
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={label}
      onPress={onPress}
    >
      {gradient ? (
        <LinearGradient
          colors={colors.gradient}
          style={[s.iconButton, { width: size, height: size, borderWidth: 0 }]}
        >
          <Icon name={name} />
        </LinearGradient>
      ) : (
        <View style={[s.iconButton, { width: size, height: size }]}>
          <Icon name={name} />
        </View>
      )}
    </Pressable>
  );
}
